ALTER TABLE public.inventory ADD CONSTRAINT inventory_reservation_bounds CHECK(quantity>=0 AND reserved>=0 AND reserved<=quantity) NOT VALID;
ALTER TABLE public.products ADD CONSTRAINT product_tax_bounds CHECK(tax_bps IS NULL OR tax_bps BETWEEN 0 AND 10000) NOT VALID;
ALTER TABLE public.products ADD CONSTRAINT product_return_bounds CHECK(return_days BETWEEN 0 AND 365) NOT VALID;
CREATE INDEX order_items_order_idx ON public.order_items(order_id);
CREATE INDEX fulfillments_order_idx ON public.fulfillments(order_id);
CREATE INDEX orders_user_idx ON public.orders(user_id,created_at DESC);
CREATE INDEX inventory_movements_product_idx ON public.inventory_movements(product_id,created_at DESC);
CREATE POLICY staff_deletion_read ON public.account_deletion_requests FOR SELECT TO authenticated USING(public.staff_has_role(ARRAY['owner','admin','support']));
CREATE OR REPLACE FUNCTION public.review_order_request(_id uuid,_status text,_note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.order_requests; BEGIN IF NOT public.staff_has_role(ARRAY['owner','admin','operations','support']) THEN RAISE EXCEPTION 'Forbidden'; END IF; IF _status NOT IN ('approved','rejected') OR length(trim(_note))<5 OR length(_note)>1000 THEN RAISE EXCEPTION 'Review decision and explanation required'; END IF; SELECT * INTO r FROM public.order_requests WHERE id=_id AND status='requested' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Request already reviewed'; END IF; UPDATE public.order_requests SET status=_status,staff_note=_note WHERE id=_id; INSERT INTO public.audit_logs(actor_id,action,entity_id,details) VALUES(auth.uid(),'request:'||_status,_id::text,jsonb_build_object('order_id',r.order_id,'note',_note)); END $$;
REVOKE ALL ON FUNCTION public.review_order_request(uuid,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.review_order_request(uuid,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.update_support_ticket(_id uuid,_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.staff_has_role(ARRAY['owner','admin','support']) THEN RAISE EXCEPTION 'Forbidden'; END IF; IF _status NOT IN ('open','in_progress','resolved') THEN RAISE EXCEPTION 'Invalid status'; END IF; UPDATE public.support_tickets SET status=_status WHERE id=_id; IF NOT FOUND THEN RAISE EXCEPTION 'Ticket unavailable'; END IF; INSERT INTO public.audit_logs(actor_id,action,entity_id) VALUES(auth.uid(),'support:'||_status,_id::text); END $$;
REVOKE ALL ON FUNCTION public.update_support_ticket(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.update_support_ticket(uuid,text) TO authenticated;